from collections import OrderedDict
from taf.transport.ssh import ssh_keywords as ssh
from taf.rfrl.procedures.resources.python.tempere.exceptions import InvalidBroadcastSelected, LoginIntoCBCFailed, \
    CbcInstanceAlreadyRunning
from taf.rfrl.procedures.resources.python.logger.logger import log_operation, log_input_and_output, log_result


class Tempere:
    def __init__(self):
        self._alias = None
        self._ssh_manager = ssh.SSHManager()
        self._script_path = None

    def open_connection(self, hostname, username, alias="tempere", **additional_params):
        """
        Opens up ssh connection to the remote
        :param hostname: hostname of the remote to connect to
        :type hostname: str
        :param username: username that should be used in authentication
        :type username: str
        :param alias: ssh connection alias
        :type alias: either SSHconnection or ProxySSHConnection object
        :param additional_params: additional params used in taf.transport.ssh.connect method such as:
                                  password, port, key_path, pkey, timeout, proxy, look_for_keys
        :type additional_params: dict
        """

        if not self._check_if_alias_exists(alias=alias):
            self._ssh_manager.connect_to(hostname=hostname, username=username, alias=alias, **additional_params)
            self._alias = alias

    def close_connection(self):
        """
        Closes ssh connection to the remote
        """
        if self._check_if_alias_exists(alias=self._alias):
            self._ssh_manager.disconnect(connection=self._alias)
            self._alias = None

    def configure_broadcast_on_cbe_simulator(self, broadcast, script_path, **config_params):
        """
        Sets up cbe simulator for either CMAS or ETWS broadcasting, using built-in option No. 22
        :param broadcast: broadcast that will be configured on cbc simulator
        :type broadcast: str
        :param script_path: path to the script that will be used to launch cbe
        :type script_path: str
        :param config_params: additional parameters that will be overwritten such as: gateway: str, port: str,
                              cbe_name: str, password: str, repetition_rate: str, data_coding_scheme: str,
                              immediate_display: bool, accept_unknown_cells: bool, use_recurrency: bool,
                              use_short_content_for_2g_and_3g: bool, etws_options: str, use_test_flag: bool
                              use_geo_fencing: bool, ip_name: str
        :type config_params: dict
        :raises InvalidBroadcastSelected: when broadcast is neither CMAS nor ETWS
        :raises CbcInstanceAlreadyRunning: when cbc instance is already running on app server
        """
        self._script_path = script_path
        if broadcast not in ["CMAS", "ETWS"]:
            raise InvalidBroadcastSelected("Selected broadcasting: {} is neither CMAS nor ETWS".format(broadcast))

        self._launch_cbe_script()
        log_operation("Configuring {} broadcast on CBC simulator...".format(broadcast))
        configuration_parameters = self._get_broadcast_configuration(broadcast=broadcast, **config_params)

        self._enter_cbc_configuration_manager()
        for parameter_value in configuration_parameters.values():
            self._ssh_manager.write_input(data="{}\r".format(parameter_value), flush=True, connection=self._alias)

        cbc_output = self._quit_cbc_configuration_manager()

        if "There already is a 'cbe' active" in cbc_output:
            raise CbcInstanceAlreadyRunning("Cannot configure broadcast because 'cbe' instance is already running!")

    def start_broadcasting(self, broadcast, eutran_cell_id, end_time, start_time=0):
        """
        Starts previously configured CMAS or ETWS broadcasting
        :param broadcast: broadcast that will be configured on cbc simulator
        :type broadcast: str
        :param eutran_cell_id: eutran cell id
        :type eutran_cell_id: str or int
        :param start_time: start time of the broadcast
        :type start_time: str or int
        :param end_time: end time of the broadcast
        :type end_time: str or int
        :raises CbcInstanceAlreadyRunning: when cbc instance is already running on app server
        """
        self._launch_cbe_script()
        self._login_to_cbc_simulator()

        log_operation("Starting {} broadcast on CBC simulator...".format(broadcast))
        self._fill_info_and_start_broadcasting(broadcast=broadcast, eutran_cell_id=eutran_cell_id,
                                               end_time=end_time, start_time=start_time)

        cbc_output = self._quit_cbc_configuration_manager()

        if "There already is a 'cbe' active" in cbc_output:
            raise CbcInstanceAlreadyRunning("Cannot start broadcast because 'cbe' instance is already running!")

        if "1300 - Login failed" in cbc_output:
            raise LoginIntoCBCFailed("Couldn't log into CBC. "
                                     "Please check if configuration is correct (terminal option number: 22)")
        elif "0 - Success" in cbc_output:
            log_result("Successfully logged into CBC")

    def _launch_cbe_script(self):
        """
        Launches CBE script
        """
        log_operation("Launching CBE script...")
        self._ssh_manager.send_command(
            command=f"ksh {self._script_path}", connection=self._alias, get_pty=True)

    def _login_to_cbc_simulator(self):
        """
        Logs into the CBC simulator using built-in option No. 1
        """
        log_operation("Logging into the CBC...")
        self._ssh_manager.write_input(data="1\r", flush=True, connection=self._alias)

    def _enter_cbc_configuration_manager(self):
        """
        Enters CBC configuration manager and sets up configuration change
        """
        self._ssh_manager.write_input(data="22\r", flush=True, connection=self._alias)
        self._ssh_manager.write_input(data="y\r", flush=True, connection=self._alias)

    def _fill_info_and_start_broadcasting(self, broadcast, eutran_cell_id, end_time, start_time=0):
        """
        Enters message sender using option No.4 and fills information in given order, then broadcasts message for 30s:
        - text to broadcast
        - cell_name
        - start time (0 = now)
        - end time (0 = never)
        :param broadcast: broadcast that will be configured on cbc simulator
        :type broadcast: str
        :param eutran_cell_id: eutran cell id
        :type eutran_cell_id: str or int
        :param start_time: start time of the broadcast
        :type start_time: str or int
        :param end_time: end time of the broadcast
        :type end_time: str or int
        """
        self._ssh_manager.write_input(data="4\r", flush=True, connection=self._alias)

        self._ssh_manager.write_input(data=f"{broadcast.lower()}1\r", flush=True, connection=self._alias)
        self._ssh_manager.write_input(data=f"TATRA_{eutran_cell_id}\r", flush=True, connection=self._alias)
        self._ssh_manager.write_input(data=f"+{start_time}\r", flush=True, connection=self._alias)
        self._ssh_manager.write_input(data=f"+{end_time}\r", flush=True, connection=self._alias)

    @log_input_and_output
    def _quit_cbc_configuration_manager(self):
        """
        Exits CBC configuration manager using option No. 23
        :return: output from cbc simulator with previously used commands
        :rtype: str
        """
        self._ssh_manager.write_input(data="23\r", flush=True, connection=self._alias)
        return self._ssh_manager.read_output(connection=self._alias)

    @log_input_and_output
    def _get_broadcast_configuration(self, broadcast, **config_params):
        """
        Gets configuration params and values for setting up a given broadcast
        :param broadcast: broadcast that will be configured on cbc simulator
        :type broadcast: str
        :param config_params: additional parameters for configuring broadcast
        :type config_params: dict
        :return: dict with configuration for given broadcast
        :rtype: dict
        """
        configuration_parameters = OrderedDict()
        configuration_parameters["gateway"] = "10.9.202.153"
        configuration_parameters["port"] = "80"
        configuration_parameters["cbe_name"] = "SRNLab"
        configuration_parameters["ip_name"] = "RAWRO"
        configuration_parameters["password"] = "wro"
        configuration_parameters["channel"] = "4370" if broadcast == "CMAS" else "4354"
        configuration_parameters["repetition_rate"] = "30"
        configuration_parameters["data_coding_scheme"] = "1"
        configuration_parameters["immediate_display"] = "n"
        configuration_parameters["accept_unknown_cells"] = "n"
        configuration_parameters["use_recurrency"] = "n"
        configuration_parameters["use_short_content_for_2g_and_3g"] = "n"
        configuration_parameters["etws_options"] = "4"
        configuration_parameters["use_test_flag"] = "n"
        configuration_parameters["use_geo_fencing"] = "n"
        configuration_parameters["accept_unknown_cells"] = "n"
        configuration_parameters["accept_unknown_cells"] = "n"

        self._adjust_config_parameters(default_config_parameters=configuration_parameters, **config_params)

        return configuration_parameters

    @staticmethod
    def _adjust_config_parameters(default_config_parameters, **config_params):
        """
        Reads values from config params and sets default value for it or custom if it's specified
        :param default_config_parameters: dict of default parameters for given broadcast
        :type default_config_parameters: dict
        :param config_params: additional parameters for configuring broadcast
        :type config_params: dict
        :return: formatted default or specified value if selected
        :rtype: str
        """
        for param_name, param_value in default_config_parameters.items():
            if config_params.get(param_name):
                if config_params[param_name] is True:
                    new_param_value = "y"
                elif config_params[param_name] is False:
                    new_param_value = "n"
                else:
                    new_param_value = str(config_params[param_name])

                default_config_parameters[param_name] = new_param_value

    def _check_if_alias_exists(self, alias):
        """
        Checks if SSH alias currently exists
        :param alias: ssh connection alias
        :type alias: either SSHconnection or ProxySSHConnection object
        :return: information whether the looked up alias exists
        :rtype: bool
        """
        return alias in [connection[0] for connection in self._ssh_manager.store.all]
